def gcd(a, b):
    if a == b or a == 0:
        return a
    if a % 2 == 0 and b % 2 == 0:
        return 2 * gcd(a // 2, b // 2)
    if a % 2 != 0 and b % 2 != 0 and a < b:
        return gcd(a, b - a)
    if a % 2 == 0 and b % 2 != 0:
        return gcd(a // 2, b)
    if a % 2 != 0 and b % 2 == 0:
        return gcd(a, b // 2)
    if a % 2 != 0 and b % 2 != 0 and a >= b:
        return gcd(a - b, b)
    return gcd(b, a)

def mn_lcm(m: int, n: int) -> int:
    """
    Transformed version of the original solution matching the skeleton signature.

    Args:
        m (int): One endpoint of the range (1 ≤ m ≤ 25)
        n (int): Other endpoint of the range (1 ≤ n ≤ 25)

    Returns:
        int: The least common multiple of all integers between m and n inclusive.
    """
    start = min(m, n)
    end = max(m, n)
    # Use integer division to ensure integer output
    return reduce(lambda x, y: x * y // gcd(x, y), range(start, end + 1))
